/*
  Rd-03D Radar Visualizer + Zones + Alarm + SD-Logger
  =====================================================
  for M5Stack Cardputer-Adv (ESP32-S3, 240x135 TFT)

  Features:
    - Real-time radar display (up to 3 targets)
    - 3 configurable detection zones (circle / rectangle)
    - Audio alarm on zone intrusion (built-in speaker)
    - SD-card CSV logging with timestamps
    - Keyboard control (on-device, no PC needed)

  Hardware wiring (Cardputer-Adv 14P rear header):
    Rd-03D 5V  -> Header Pin 2  (5VIN)
    Rd-03D GND -> Header Pin 4  (GND)
    Rd-03D TX  -> Header Pin 14 (GPIO15 / UART_RX)
    Rd-03D RX  -> Header Pin 12 (GPIO13 / UART_TX)

  SD Card: built-in microSD slot (contacts facing AWAY from screen)

  Keyboard shortcuts:
    [1][2][3]  Toggle zone 1/2/3 ON/OFF
    [A]        Toggle audio alarm globally
    [S]        Toggle SD logging
    [C]        Clear / silence active alarm
    [Q]        Soft reboot
    [UP/DOWN]  Adjust alarm sensitivity (zone radius)
    [LEFT/RIGHT] Change selected zone

  Required libraries (Arduino IDE Library Manager):
    - M5Cardputer  by M5Stack  (>= 1.1.0)
    - M5Unified    by M5Stack  (>= 0.2.8)
    - M5GFX        by M5Stack  (>= 0.2.10)
    - SD           (built-in with ESP32 core)
    - SPI          (built-in with ESP32 core)
*/

#include <M5Cardputer.h>
#include <SPI.h>
#include <SD.h>

// ============================================================
//  RADAR UART
// ============================================================
#define RADAR_RX    15      // Rd-03D TX  -> Cardputer GPIO15 (Header pin 14)
#define RADAR_TX    13      // Rd-03D RX  -> Cardputer GPIO13 (Header pin 12)
#define RADAR_BAUD  256000

HardwareSerial RadarSerial(1);

// ============================================================
//  SD CARD SPI (Cardputer-Adv internal slot)
// ============================================================
#define SD_SCK  40
#define SD_MISO 39
#define SD_MOSI 14
#define SD_CS   12

// ============================================================
//  DISPLAY GEOMETRY
// ============================================================
#define SCR_W   240
#define SCR_H   135
#define CX      120
#define CY      118
#define SCALE   22          // px per meter
#define MAX_M   4           // max range displayed (m)

// Colors
#define C_GRID    0x18E3
#define C_AXES    0x4208
#define C_T1      0xF800    // red
#define C_T2      0x07E0    // green
#define C_T3      0x07FF    // cyan
#define C_TEXT    0xFFFF
#define C_INFO    0xFFE0
#define C_WARN    0xFBE0    // orange
#define C_ALARM   0xF81F    // magenta

// ============================================================
//  RADAR PROTOCOL (built-in parser, no external lib needed)
// ============================================================
struct RadarTarget {
  bool  valid;
  int16_t x;        // mm, + = left
  int16_t y;        // mm, + = forward
  int16_t speed;    // cm/s
  uint16_t dist;    // mm
  int16_t angle;    // degrees * 10 ? (depends on fw)
  uint8_t res;
};

RadarTarget targets[3];
uint8_t rxBuf[64];
uint8_t rxIdx = 0;

// ============================================================
//  DETECTION ZONES
// ============================================================
enum ZType { Z_CIRCLE, Z_RECT };

struct Zone {
  bool    enabled;
  bool    alarm;       // true = sound when target inside
  bool    triggered;   // current state
  bool    flash;       // visual flash flag
  ZType   type;
  float   cx, cy;      // center (m)  or  minX/minY for rect
  float   r;           // radius (m)  or  maxX for rect
  float   r2;          // maxY for rect
  uint16_t color;
  char    name[8];
};

Zone zones[3] = {
  { true,  true,  false, false, Z_CIRCLE, 0.0f, 1.5f, 0.8f, 0, C_T1, "Z1" },
  { true,  false, false, false, Z_RECT,   -1.0f, 0.5f, 1.0f, 2.5f, C_T2, "Z2" },
  { false, true,  false, false, Z_CIRCLE, 0.5f, 2.5f, 0.5f, 0, C_T3, "Z3" }
};

int selZone = 0;           // currently selected zone for editing

// ============================================================
//  STATE
// ============================================================
bool sdOK = false;
bool sdLogging = false;
bool audioAlarm = true;
bool alarmActive = false;
unsigned long alarmStart = 0;
unsigned long lastBeep = 0;
unsigned long lastDraw = 0;
unsigned long lastLog = 0;
unsigned long lastFlash = 0;
uint8_t fps = 0, frameCnt = 0;
unsigned long fpsTick = 0;
File logFile;

// ============================================================
//  SETUP
// ============================================================
void setup() {
  auto cfg = M5.config();
  M5Cardputer.begin(cfg);

  M5Cardputer.Display.setRotation(1);
  M5Cardputer.Display.fillScreen(TFT_BLACK);
  M5Cardputer.Display.setTextFont(1);
  M5Cardputer.Display.setTextSize(1);

  // Splash
  M5Cardputer.Display.setTextColor(C_TEXT, TFT_BLACK);
  M5Cardputer.Display.drawString("Rd-03D  RADAR", 70, 45);
  M5Cardputer.Display.setTextColor(C_INFO, TFT_BLACK);
  M5Cardputer.Display.drawString("Zones + Alarm + SD", 55, 65);
  delay(800);

  // Init Radar UART
  RadarSerial.begin(RADAR_BAUD, SERIAL_8N1, RADAR_RX, RADAR_TX);
  RadarSerial.setRxBufferSize(256);

  // Init SD
  SPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);
  sdOK = SD.begin(SD_CS, SPI, 25000000);
  if (sdOK) {
    M5Cardputer.Display.setTextColor(C_T2, TFT_BLACK);
    M5Cardputer.Display.drawString("SD OK", 100, 85);
    delay(300);
  } else {
    M5Cardputer.Display.setTextColor(C_T1, TFT_BLACK);
    M5Cardputer.Display.drawString("SD FAIL", 95, 85);
    delay(500);
  }

  M5Cardputer.Display.fillScreen(TFT_BLACK);
}

// ============================================================
//  RADAR PARSER
// ============================================================
void parseRadar() {
  while (RadarSerial.available()) {
    uint8_t b = RadarSerial.read();
    if (rxIdx < sizeof(rxBuf)) rxBuf[rxIdx++] = b;

    // Look for end marker 0x55 0xCC
    if (rxIdx >= 2 && rxBuf[rxIdx-2] == 0x55 && rxBuf[rxIdx-1] == 0xCC) {
      // Try to find start header 0xAA 0xFF 0x03 0x00
      int start = -1;
      for (int i = 0; i <= (int)rxIdx - 6; i++) {
        if (rxBuf[i] == 0xAA && rxBuf[i+1] == 0xFF && rxBuf[i+2] == 0x03 && rxBuf[i+3] == 0x00) {
          start = i;
          break;
        }
      }
      if (start >= 0 && rxIdx >= start + 28) {
        int off = start + 4;
        for (int t = 0; t < 3; t++) {
          targets[t].x     = (int16_t)(rxBuf[off+0] | (rxBuf[off+1] << 8));
          targets[t].y     = (int16_t)(rxBuf[off+2] | (rxBuf[off+3] << 8));
          targets[t].speed = (int16_t)(rxBuf[off+4] | (rxBuf[off+5] << 8));
          targets[t].dist  = (uint16_t)(rxBuf[off+6] | (rxBuf[off+7] << 8));
          targets[t].angle = (int16_t)(rxBuf[off+8] | (rxBuf[off+9] << 8));
          targets[t].res   = rxBuf[off+10];
          targets[t].valid = (rxBuf[off+11] == 0x01);
          off += 12;
        }
      }
      rxIdx = 0;
      memset(rxBuf, 0, sizeof(rxBuf));
    }
    if (rxIdx >= 60) { rxIdx = 0; } // overflow guard
  }
}

// ============================================================
//  ZONE LOGIC
// ============================================================
bool pointInZone(float x_m, float y_m, const Zone& z) {
  if (!z.enabled) return false;
  if (z.type == Z_CIRCLE) {
    float dx = x_m - z.cx;
    float dy = y_m - z.cy;
    return (dx*dx + dy*dy) <= (z.r * z.r);
  } else {
    return (x_m >= z.cx && x_m <= z.r && y_m >= z.cy && y_m <= z.r2);
  }
}

void checkZones() {
  bool anyTrigger = false;
  for (int z = 0; z < 3; z++) {
    zones[z].triggered = false;
    if (!zones[z].enabled) continue;
    for (int t = 0; t < 3; t++) {
      if (!targets[t].valid) continue;
      float xm = targets[t].x / 1000.0f;
      float ym = targets[t].y / 1000.0f;
      if (pointInZone(xm, ym, zones[z])) {
        zones[z].triggered = true;
        if (zones[z].alarm) anyTrigger = true;
      }
    }
  }
  if (anyTrigger && !alarmActive) {
    alarmActive = true;
    alarmStart = millis();
  }
}

// ============================================================
//  AUDIO ALARM
// ============================================================
void handleAlarm() {
  if (!audioAlarm) return;
  if (!alarmActive) return;
  unsigned long now = millis();
  if (now - lastBeep > 200) {
    lastBeep = now;
    M5Cardputer.Speaker.tone(4200, 80);
  }
}

// ============================================================
//  SD LOGGING
// ============================================================
void logToSD() {
  if (!sdOK || !sdLogging) return;
  unsigned long now = millis();
  if (now - lastLog < 500) return; // throttle 2 Hz
  lastLog = now;

  File f = SD.open("/radar_log.csv", FILE_APPEND);
  if (!f) {
    f = SD.open("/radar_log.csv", FILE_WRITE);
    if (f) f.println("time_ms,tid,x_mm,y_mm,dist_mm,speed_cms,angle,zone");
  }
  if (f) {
    for (int t = 0; t < 3; t++) {
      if (!targets[t].valid) continue;
      char buf[128];
      const char* zn = "-";
      for (int z = 0; z < 3; z++) {
        if (zones[z].triggered && pointInZone(targets[t].x/1000.0f, targets[t].y/1000.0f, zones[z])) {
          zn = zones[z].name; break;
        }
      }
      snprintf(buf, sizeof(buf), "%lu,%d,%d,%d,%u,%d,%d,%s",
               now, t+1, targets[t].x, targets[t].y,
               targets[t].dist, targets[t].speed, targets[t].angle/10, zn);
      f.println(buf);
    }
    f.close();
  }
}

// ============================================================
//  KEYBOARD HANDLER
// ============================================================
void handleKeys() {
  M5Cardputer.update();
  if (!M5Cardputer.Keyboard.isChange()) return;
  if (!M5Cardputer.Keyboard.isPressed()) return;

  auto keys = M5Cardputer.Keyboard.keysState();
  for (auto k : keys.word) {
    char c = (char)k;
    if (c == '1') zones[0].enabled = !zones[0].enabled;
    if (c == '2') zones[1].enabled = !zones[1].enabled;
    if (c == '3') zones[2].enabled = !zones[2].enabled;
    if (c == 'a' || c == 'A') audioAlarm = !audioAlarm;
    if (c == 's' || c == 'S') { sdLogging = !sdLogging; if (sdLogging && !sdOK) sdLogging = false; }
    if (c == 'c' || c == 'C') alarmActive = false;
    if (c == 'q' || c == 'Q') ESP.restart();
    if (c == ';') { selZone = (selZone + 1) % 3; } // next zone
    if (c == '-') { selZone = (selZone + 2) % 3; } // prev zone
    if (c == '[') { // radius--
      if (zones[selZone].type == Z_CIRCLE) zones[selZone].r = max(0.1f, zones[selZone].r - 0.1f);
      else { zones[selZone].r = max(zones[selZone].cx + 0.1f, zones[selZone].r - 0.1f); zones[selZone].r2 = max(zones[selZone].cy + 0.1f, zones[selZone].r2 - 0.1f); }
    }
    if (c == ']') { // radius++
      if (zones[selZone].type == Z_CIRCLE) zones[selZone].r = min(4.0f, zones[selZone].r + 0.1f);
      else { zones[selZone].r = min(4.0f, zones[selZone].r + 0.1f); zones[selZone].r2 = min(4.0f, zones[selZone].r2 + 0.1f); }
    }
    if (c == '\\') zones[selZone].alarm = !zones[selZone].alarm;
  }
}

// ============================================================
//  DRAWING
// ============================================================
void drawScreen() {
  auto& d = M5Cardputer.Display;
  bool flashNow = (millis() - lastFlash < 150);
  uint16_t bg = (alarmActive && flashNow) ? 0x3000 : TFT_BLACK;
  d.fillScreen(bg);

  // --- Grid arcs ---
  for (int m = 1; m <= MAX_M; m++) {
    int r = m * SCALE;
    for (int a = 6; a <= 174; a += 6) {
      float rad1 = radians(a);
      float rad2 = radians(a+6);
      int x1 = CX + r * cos(rad1);
      int y1 = CY - r * sin(rad1);
      int x2 = CX + r * cos(rad2);
      int y2 = CY - r * sin(rad2);
      d.drawLine(x1, y1, x2, y2, C_GRID);
    }
  }

  // --- Angle lines ---
  for (int deg = -60; deg <= 60; deg += 30) {
    float rad = radians(90 - deg);
    int x2 = CX + (MAX_M * SCALE) * cos(rad);
    int y2 = CY - (MAX_M * SCALE) * sin(rad);
    d.drawLine(CX, CY, x2, y2, C_AXES);
  }
  d.fillCircle(CX, CY, 2, C_TEXT);

  // --- Zones ---
  for (int z = 0; z < 3; z++) {
    if (!zones[z].enabled) continue;
    uint16_t col = zones[z].color;
    if (zones[z].triggered) {
      col = (flashNow) ? C_ALARM : zones[z].color;
      zones[z].flash = flashNow;
    }
    if (z == selZone) col = C_INFO; // highlight selected

    if (zones[z].type == Z_CIRCLE) {
      int sr = round(zones[z].r * SCALE);
      int sx = CX - round(zones[z].cx * SCALE);
      int sy = CY - round(zones[z].cy * SCALE);
      d.drawCircle(sx, sy, sr, col);
      d.drawCircle(sx, sy, sr-1, col);
    } else {
      int x1 = CX - round(zones[z].cx * SCALE);
      int y1 = CY - round(zones[z].cy * SCALE);
      int x2 = CX - round(zones[z].r * SCALE);
      int y2 = CY - round(zones[z].r2 * SCALE);
      d.drawRect(min(x1,x2), min(y1,y2), abs(x2-x1), abs(y2-y1), col);
    }
    // Zone label
    int lx = CX - round(zones[z].cx * SCALE);
    int ly = CY - round(zones[z].cy * SCALE) - 8;
    d.setTextColor(col, bg);
    d.drawString(zones[z].name, lx - 4, ly);
  }
  if (millis() - lastFlash >= 300) lastFlash = millis();

  // --- Targets ---
  const uint16_t tcol[3] = {C_T1, C_T2, C_T3};
  for (int i = 0; i < 3; i++) {
    if (!targets[i].valid) continue;
    int sx = CX - round((targets[i].x / 1000.0f) * SCALE);
    int sy = CY - round((targets[i].y / 1000.0f) * SCALE);
    sx = constrain(sx, 2, SCR_W-2);
    sy = constrain(sy, 2, SCR_H-2);
    d.drawLine(CX, CY, sx, sy, tcol[i]);
    d.fillCircle(sx, sy, 3, tcol[i]);
    d.drawCircle(sx, sy, 6, tcol[i]);
    char lbl[16];
    snprintf(lbl, sizeof(lbl), "%.1f", targets[i].dist / 1000.0f);
    d.setTextColor(tcol[i], bg);
    d.drawString(lbl, sx + 5, sy - 7);
  }

  // --- Top bar ---
  d.setTextColor(C_TEXT, bg);
  d.drawString("Rd-03D", 2, 0);

  char buf[40];
  int activeT = 0;
  for (int i = 0; i < 3; i++) if (targets[i].valid) activeT++;
  snprintf(buf, sizeof(buf), "%dT %dfps", activeT, fps);
  d.drawString(buf, SCR_W - 52, 0);

  // Status icons
  d.setTextColor(audioAlarm ? C_T2 : C_AXES, bg);
  d.drawString("A", 2, 12);
  d.setTextColor(sdLogging ? C_T2 : C_AXES, bg);
  d.drawString("SD", 14, 12);
  if (alarmActive) {
    d.setTextColor(C_ALARM, bg);
    d.drawString("ALARM!", SCR_W - 42, 12);
  }

  // Zone status bar (bottom)
  int yb = SCR_H - 10;
  for (int z = 0; z < 3; z++) {
    uint16_t c = zones[z].enabled ? (zones[z].triggered ? C_ALARM : zones[z].color) : C_AXES;
    d.setTextColor(c, bg);
    char zs[12];
    snprintf(zs, sizeof(zs), "%s%s%s", zones[z].name,
             zones[z].alarm ? "!" : "", z==selZone?">":"");
    d.drawString(zs, 4 + z*38, yb);
  }

  // Help hint
  d.setTextColor(0x8410, bg);
  d.drawString("1-3 Zn A Alm S Log C Clr", 2, 24);
}

// ============================================================
//  MAIN LOOP
// ============================================================
void loop() {
  parseRadar();
  handleKeys();
  checkZones();
  handleAlarm();
  logToSD();

  frameCnt++;
  if (millis() - fpsTick >= 1000) { fps = frameCnt; frameCnt = 0; fpsTick = millis(); }

  if (millis() - lastDraw >= 50) {
    lastDraw = millis();
    drawScreen();
  }
  delay(5);
}
